using System;
using System.Linq;
using System.Reflection;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshTerritoriesSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('prior',@prior::json,'runs',(SELECT json_agg(w ORDER BY arena,day) FROM revora_clan_wars w WHERE run IN(SELECT run FROM revora_clan_war_entries WHERE uid=@uid)),'entries',(SELECT json_agg(e ORDER BY run) FROM revora_clan_war_entries e WHERE uid=@uid),'awards',(SELECT json_agg(a ORDER BY run) FROM revora_clan_war_awards a WHERE uid=@uid),'territories',(SELECT json_agg(t ORDER BY arena) FROM revora_clan_territories t WHERE clan=@clan))::text","prior",FreshAffiliationsSnapshot(p),"uid",(long)p.Entity.UID,"clan",(long)p.Entity.ClanId));}
    static void FreshTerritoriesProcess(string phase){
        var p=FreshLoadSaved(true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);Require(!p.Fake && p.Account.State==AccountTable.AccountState.Player && !PirateFenced(p) && p.Entity.GetClan!=null && (int)p.Entity.ClanRank==100);Server.GamePool=new[]{p};var results=Feature("ClanWarResults");DateTime now=new DateTime(2041,3,1,20,0,0,DateTimeKind.Utc);results.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        if((bool)Sql("SELECT to_regclass('revora_fresh_territories_probe') IS NULL")){
            Require(phase.EndsWith("capture") && FreshAffiliationsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_affiliations_probe")) && (long)Sql("SELECT count(*) FROM revora_clan_wars WHERE day BETWEEN 20410301 AND 20410305")==0 && (long)Sql("SELECT count(*) FROM revora_clan_war_awards WHERE uid=@uid","uid",(long)p.Entity.UID)==0);Sql("CREATE TABLE revora_fresh_territories_probe(stage text,snapshot text);INSERT INTO revora_fresh_territories_probe VALUES('new',@snapshot)","snapshot",FreshTerritoriesSnapshot(p));
        }
        Require(FreshTerritoriesSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_territories_probe")));string stage=Convert.ToString(Sql("SELECT stage FROM revora_fresh_territories_probe"));
        if(phase.EndsWith("capture")){
            Require(stage=="new");FreshClassicTalk(p,1011,10012,0);var bank=p.Warehouses.First(w=>(uint)w.Key==10012).Value;int store=Math.Max(0,p.Inventory.Count-35);Require(bank.Count+store<=60);foreach(var item in p.Inventory.Objects.Where(i=>i.Days==0).Take(store).ToArray()){
                var frame=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,frame);Revora.Network.Writer.WriteUInt16(1102,2,frame);Revora.Network.Writer.WriteUInt32(10012,4,frame);frame[12]=1;frame[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,frame);Warehouse.Process(frame,p);Require(!p.Inventory.ContainsUID(item.UID) && bank.ContainsUID(item.UID));
            }
            Require(p.Inventory.Count<=35);ushort[] cities={1002,1011,1020,1000,1015};uint[] envoys={101895,101901,101905,101913,101909};
            for(int index=0;index<5;index++){
                now=new DateTime(2041,3,1+index,20,0,0,DateTimeKind.Utc);var npc=Kernel.Maps[cities[index]].Npcs[envoys[index]];p.Entity.Teleport(cities[index],npc.X,(ushort)(npc.Y+1));var war=ClanWar.Tournaments[index];war.GetType().GetMethod("Begin",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(war,new object[]{now,20410301+index,false});Require(war.Open);
                foreach(byte action in new byte[]{6,8}){var frame=new byte[148];Revora.Network.Writer.WriteUInt16(140,0,frame);Revora.Network.Writer.WriteUInt16(1313,2,frame);frame[4]=action;Revora.Network.Writer.WriteUInt32(npc.UID,12,frame);System.Text.Encoding.ASCII.GetBytes("TQClient").CopyTo(frame,140);ClanWar.Process(frame,p);}Require(p.Entity.MapID==ClanWar.GetMap((ClanWar.ClanArena)index));
                uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;ulong gold=p.Entity.Money;var prior=p.Inventory.Objects.Select(i=>i.UID).ToArray();now=now.AddMinutes(20);war.GetType().GetMethod("Work",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(war,new object[]{0});var added=p.Inventory.Objects.Where(i=>!prior.Contains(i.UID)).ToArray();Require(!war.Open && p.Entity.MapID==1002 && added.Length==1 && added[0].Bound && ConquerItemInformation.BaseInformations[added[0].ID].PurificationLevel==7 && prior.All(uid=>p.Inventory.ContainsUID(uid)) && p.Entity.Money==gold);
                Require((bool)Sql("SELECT EXISTS(SELECT 1 FROM revora_clan_war_awards a JOIN revora_clan_wars w ON w.run=a.run WHERE a.uid=@uid AND w.day=@day AND w.arena=@arena AND w.state='complete' AND w.winner=@clan AND a.paid_at IS NOT NULL AND a.soul_uid=@soul AND a.cp=@cp AND a.rvp=@rvp)","uid",(long)p.Entity.UID,"day",20410301+index,"arena",index,"clan",(long)p.Entity.ClanId,"soul",(long)added[0].UID,"cp",(long)p.Entity.ConquerPoints-cp,"rvp",(long)p.Entity.RevoraPoint-rvp));System.Console.WriteLine("[fresh-territories] city="+cities[index]+" cp="+(p.Entity.ConquerPoints-cp)+" rvp="+(p.Entity.RevoraPoint-rvp));
            }
            new TitleStorage().Login(p);Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_fresh_territories_probe SET stage='paid',snapshot=@snapshot","snapshot",FreshTerritoriesSnapshot(p));
        }else Require(phase.EndsWith("reload") && stage=="paid");
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id BETWEEN 10305 AND 10309 AND source='clan-territory-v1'","uid",(long)p.Entity.UID)==5 && (long)Sql("SELECT count(*) FROM revora_clan_war_awards a JOIN items i ON i.uid=a.soul_uid WHERE a.uid=@uid AND a.paid_at IS NOT NULL AND i.entityid=a.uid AND i.bound=1 AND i.id=a.soul_type","uid",(long)p.Entity.UID)==5 && (long)Sql("SELECT count(*) FROM revora_clan_territories WHERE clan=@clan AND arena BETWEEN 0 AND 4","clan",(long)p.Entity.ClanId)==5);
        string exact=FreshTerritoriesSnapshot(p);Require(!(bool)Call(results,"Pay",p));for(int index=0;index<5;index++){var war=ClanWar.Tournaments[index];Require(war.Client.UID==p.Entity.ClanId);war.GetType().GetMethod("Begin",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(war,new object[]{new DateTime(2041,3,1+index,20,0,0,DateTimeKind.Utc),20410301+index,false});Require(!war.Open);}Require(exact==FreshTerritoriesSnapshot(p) && exact==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_territories_probe")) && !PirateFenced(p));System.Console.WriteLine("[career-process] "+phase+"-passed bag="+p.Inventory.Count+" cp="+p.Entity.ConquerPoints+" rvp="+p.Entity.RevoraPoint);Server.CommandsAI("@close");throw new InvalidOperationException("Fresh territories did not close.");
    }
}
